    var KBD_ROWS = [['mod+k', 'Search'], ['mod+s', 'Save'], ['mod+shift+p', 'Open the command list'], ['alt+arrowup', 'Move the row up'], ['shift+?', 'Show the shortcuts'], ['g i', 'Go to the inventory'], ['escape', 'Close the layer']];

